<?php
declare(strict_types=1);
namespace Modules\Auxiliary;
use App\{Auth,Audit,DB,Http,View};
use PDO;
final class Controller {
    private const SECTIONS=['contracts'=>['Договоры',['contract']],'invoices'=>['Счета покупателям',['invoice']],'realizations'=>['Реализации / УПД',['realization']],'payments'=>['Оплаты и возвраты',['receipt','expense','cash-receipt','cash-expense']],'orders'=>['Платёжные поручения',['payment-order']],'balances'=>['Остатки и обороты',['opening','closing','turnover']],'adjustments'=>['Корректировки и проводки',['adjustment','manual','posting']],'purchases'=>['Расходы поставщиков',['purchase']],'counterparties'=>['Контрагенты',['counterparty']],'services'=>['Услуги',['service']],'banks'=>['Банки',['bank']],'accounts'=>['Банковские счета',['account']],'organization'=>['Наша организация',['organization']],'reference-data'=>['Прочие справочные данные',['lookup']]];
    private static function table(array $headers,array $rows):string {$s='<section class="table-card registry-ui-card registry-ui-scroll"><div class="table-scroll"><table class="table registry-ui-table registry-ui-data"><thead><tr>';foreach($headers as $h)$s.='<th>'.View::e($h).'</th>';$s.='</tr></thead><tbody>';foreach($rows as $row){$s.='<tr>';foreach($row as $v)$s.='<td>'.$v.'</td>';$s.='</tr>';}if(!$rows)$s.='<tr><td colspan="'.count($headers).'">Нет сохранённых записей.</td></tr>';return $s.'</tbody></table></div></section>';}
    private static function query(string $sql,array $args=[]):array {$q=DB::pdo()->prepare($sql);$q->execute($args);return $q->fetchAll();}
    private static function link(string $url,string $label):string{return '<a href="'.View::e($url).'">'.View::e($label).'</a>';}
    public static function index():string {Auth::requirePermission('rental.read');$s=View::heading('Дополнительные разделы','Справочники источников, технический реестр и сохранённые наблюдения рынка.');foreach(['/auxiliary/premises'=>'Помещения','/auxiliary/records'=>'Реестры источников','/auxiliary/analytics'=>'Аналитика аренды','/auxiliary/quality'=>'Проверка данных','/auxiliary/market/dashboard'=>'Мониторинг аренды']as $url=>$label)$s.='<p>'.self::link($url,$label).'</p>';return View::page('Дополнительные разделы',$s);}
    public static function premises(): string
    {
        Auth::requirePermission('rental.read');
        $user=Auth::user();
        if (!empty($user['grants_configured']) && \App\PagePolicy::level('auxiliary.premises',$user)<1) throw new \RuntimeException('Недостаточно прав для просмотра помещений.',403);
        if (isset($_GET['resolve']) || isset($_POST['issue_key'])) return PremiseIssueController::index();
        if (!isset($_GET['card']) && ($_GET['legacy']??'')!=='1' && DB::pdo()->query('SELECT 1 FROM aux_confirmed_premises LIMIT 1')->fetchColumn()) return ConfirmedController::index();
        return LegacyPremisesController::index();
    }
    public static function records():string {
        Auth::requirePermission('rental.read');$section=(string)($_GET['section']??'contracts');if(!isset(self::SECTIONS[$section]))throw new \RuntimeException('Раздел не найден',404);[$title,$kinds]=self::SECTIONS[$section];$s=View::heading($title,'Неизменяемые оригиналы источников и связанные учетные записи.');$s.='<form><select name="section" class="field-select">';foreach(self::SECTIONS as $id=>[$label])$s.='<option value="'.$id.'"'.($section===$id?' selected':'').'>'.View::e($label).'</option>';$q=trim((string)($_GET['q']??''));$s.='</select><input class="input" name="q" value="'.View::e($q).'" placeholder="Номер, наименование, ИНН"><button class="btn">Найти</button></form>';$where=implode(',',array_fill(0,count($kinds),'?'));$args=array_merge($kinds,['%'.$q.'%','%'.$q.'%','%'.$q.'%']);$out=[];foreach(self::query('SELECT * FROM aux_source_records WHERE kind IN ('.$where.') AND (title LIKE ? OR number LIKE ? OR inn LIKE ?) ORDER BY record_date DESC,title LIMIT 500',$args)as $r)$out[]=[View::e($r['title']),View::e($r['number']),View::e($r['record_date']),View::e($r['amount']??'Неизвестно'),View::e($r['inn']),View::e($r['collection']),View::e($r['source_key']),View::e($r['deleted']?'Удалён в источнике':($r['present']?'Присутствует':'Отсутствует'))];$s.=self::table(['Запись','Номер','Дата','Сумма','ИНН','Коллекция','ID источника','Статус'],$out);return View::page($title,$s);
    }
    public static function analytics():string {Auth::requirePermission('rental.read');$s=View::heading('Аналитика аренды','Оперативные данные обязательного пакета; архивные счета исключены из расчётного остатка.');$out=[];foreach(self::query('SELECT c.status,COUNT(*) records,SUM(c.amount) rent,SUM(c.amount IS NULL) unknowns FROM contracts c GROUP BY c.status')as $r)$out[]=[View::e($r['status']),View::e($r['records']),View::e($r['rent']??'Неизвестно'),View::e($r['unknowns'])];$s.=self::table(['Статус договора','Договоров','Подтверждённая аренда в месяц','Неподтверждённых сумм'],$out);$out=[];foreach(self::query("SELECT p.id,p.name,COUNT(*) invoices,SUM(i.amount) charged,SUM(i.paid) paid,SUM(i.amount-i.paid) balance,SUM(i.amount IS NULL OR i.paid IS NULL) unknowns FROM parties p JOIN contracts c ON c.party_id=p.id JOIN invoices i ON i.contract_id=c.id WHERE i.status='active' GROUP BY p.id,p.name ORDER BY p.name")as $r)$out[]=[self::link('/rental/invoices?q='.urlencode($r['name']),$r['name']),View::e($r['invoices']),View::e($r['charged']??'Неизвестно'),View::e($r['paid']??'Неизвестно'),View::e($r['balance']??'Неизвестно'),View::e($r['unknowns'])];$s.='<h2>Расчёты контрагентов</h2>'.self::table(['Контрагент','Счетов','Начислено','Оплачено','Остаток по известным суммам','Неподтверждённых'],$out);return View::page('Аналитика аренды',$s);}
    public static function quality():string {Auth::requirePermission('rental.read');$s=View::heading('Проверка данных','Спорные связи и результаты проверки источников.');$out=[];foreach(self::query('SELECT * FROM aux_issues ORDER BY state,id')as $r)$out[]=[View::e($r['category']),View::e($r['title']),View::e($r['detail']),View::e($r['state']),View::e($r['note']),View::e($r['revision'])];$s.=self::table(['Категория','Вопрос','Описание','Статус','Примечание','Редакция'],$out);$out=[];foreach(self::query('SELECT state_hash,mapping_hash,validator_version,validated_at FROM rental_import_validations ORDER BY validated_at DESC')as $r)$out[]=array_map(View::e(...),array_values($r));return View::page('Проверка данных',$s.'<h2>Импортные проверки</h2>'.self::table(['State SHA256','Mapping SHA256','Версия проверки','Время'],$out));}
    public static function market(string $page):string {
        if ($page === 'settings') return MarketSettingsController::index();
        Auth::requirePermission('rental.read');$titles=['dashboard'=>'Объявления','runs'=>'Запуски','comparison'=>'Сравнение','history'=>'Динамика','settings'=>'Настройки'];$title=$titles[$page]??throw new \RuntimeException('Раздел не найден',404);$s=View::heading($title,'Сохранённые наблюдения рынка аренды');$s.='<div class="registry-ui-tabs">';foreach($titles as $key=>$label)$s.=self::link('/auxiliary/market/'.$key,$label).' ';$s.='</div>';$runs=self::query('SELECT * FROM market_runs ORDER BY created_at DESC,id DESC');$selected=(int)($_GET['run']??($runs[0]['id']??0));
        if($page==='runs'){$rows=[];foreach($runs as $r)$rows[]=[self::link('/auxiliary/market/dashboard?run='.$r['id'],$r['run_key']),View::e($r['created_at']),View::e($r['records_count']),View::e($r['snapshot_hash']),View::e($r['imported_at'])];$s.=self::table(['Запуск','Дата наблюдения','Объявлений','SHA256','Импортирован'],$rows);$s.='<p>Новый live-сбор не подключён. Проверенный пакет COMPLETE можно загрузить отдельной локальной командой импорта.</p>';
        }elseif($page==='comparison'){$s.='<form><label>Ранний запуск<select name="before">';foreach($runs as $r)$s.='<option value="'.$r['id'].'">'.View::e($r['run_key']).'</option>';$s.='</select></label><label>Поздний запуск<select name="after">';foreach($runs as $r)$s.='<option value="'.$r['id'].'">'.View::e($r['run_key']).'</option>';$s.='</select></label><button class="btn">Сравнить</button></form>';if(isset($_GET['before'],$_GET['after'])){$result=Comparison::compare(Market::snapshot((int)$_GET['before']),Market::snapshot((int)$_GET['after']));$out=[];foreach($result['events']as $r)$out[]=[View::e($r['source']),View::e($r['source_id']),View::e($r['address']),View::e($r['status']),View::e($r['price']['before']??'—'),View::e($r['price']['after']??'—'),View::e($r['price']['delta']??'—'),View::e($r['coverage']['state']),View::e($r['reason'])];$s.='<p>'.View::e($result['notice']).'</p>'.self::table(['Источник','ID','Адрес','Состояние','До','После','Изменение','Покрытие','Пояснение'],$out);}
        }elseif($page==='settings'){$s.='<p>Параметры сохранённого запуска не редактируются. Новый native PHP collector ещё не подключён; чужие runtime и browser automation не используются.</p>';if($selected){$snapshot=Market::snapshot($selected);$s.='<pre>'.View::e(json_encode($snapshot['settings'],JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR)).'</pre>';}
        }else{$args=[];$where='';if($page==='dashboard'){$where='WHERE o.run_id=?';$args[]=$selected;}else{$source=(string)($_GET['source_id']??'');$s.='<form><input class="input" name="source_id" placeholder="ID объявления" value="'.View::e($source).'"><button class="btn">Показать историю</button></form>';if($source!==''){$where='WHERE o.source_id=?';$args[]=$source;}}$out=[];foreach(self::query('SELECT o.*,r.run_key,r.created_at observed_at FROM market_observations o JOIN market_runs r ON r.id=o.run_id '.$where.' ORDER BY r.created_at DESC,o.position LIMIT 500',$args)as $r)$out[]=[View::e($r['observed_at']),View::e($r['source']),View::e($r['object_type']),self::link('/auxiliary/market/history?source_id='.urlencode((string)$r['source_id']),(string)($r['source_id']??'Нет надёжного ID')),View::e($r['address']),View::e($r['area']??'Неизвестно'),View::e($r['price_rub']??'Неизвестно'),View::e($r['price_period']),View::e($r['annual_rate_rub_m2']??'Неизвестно')];$s.=self::table(['Дата наблюдения','Источник','Тип','ID','Адрес','Площадь','Цена RUB','Период','Годовая ставка RUB/м²'],$out);}
        return View::page($title.' · Мониторинг аренды',$s);
    }
}
